static char *read_file(const char *path)
{
    FILE *f = fopen(path, "r");
    if (!f) { perror(path); exit(1); }
    fseek(f, 0, SEEK_END);
    long len = ftell(f);
    fseek(f, 0, SEEK_SET);
    char *buf = malloc((size_t)len + 2);
    if (!buf) { fprintf(stderr, "oom\n"); exit(1); }
    size_t n = fread(buf, 1, (size_t)len, f);
    buf[n] = '\0';
    fclose(f);
    return buf;
}

/* Dump the 80x30 ASCII framebuffer at 0xF000 to stderr.
 * Each row is printed as up to 80 chars, trimmed of trailing whitespace, + '\n'.
 * Non-printable bytes (including \0) render as ' '. */
static void dump_framebuffer(void)
{
    for (int row = 0; row < 30; row++) {
        char line[81];
        for (int col = 0; col < 80; col++) {
            uint8_t b = g_cores[0].bram[0xF000 + row * 80 + col];
            line[col] = (b >= 32 && b < 127) ? (char)b : ' ';
        }
        int end = 80;
        while (end > 0 && line[end - 1] == ' ') end--;
        line[end] = '\0';
        fprintf(stderr, "%s\n", line);
    }
}

/* Dump the bitmap framebuffer to a binary PPM (P6) file. The framebuffer
 * lives in SDRAM at chip byte 0x10000 (= word 0x4000); resolution and
 * pixel format come from g_disp_mode (the DISP_MODE MMIO register):
 *
 *   bit 0 (mode_320)   → 320x240 source resolution (vs 640x480)
 *   bit 1 (mode_8bpp)  → 8-bit indexed (vs 32bpp XRGB), 4 indices per pbus
 *                        word, indices look up an XRGB triple in g_disp_lut
 *
 * In all modes the source pixel format on disk is XRGB; bits[23:16]=R,
 * [15:8]=G, [7:0]=B. The PPM is written at the *fb resolution* (no pixel
 * doubling in the output) — viewers can scale. */
static void dump_bitmap_fb(const char *path)
{
    if (!sdram) {
        fprintf(stderr, "sim_c: -fb requested but SDRAM was never allocated; nothing to dump\n");
        return;
    }
    int mode_320  = (g_disp_mode & 0x1u) != 0;
    int mode_8bpp = (g_disp_mode & 0x2u) != 0;
    int w = mode_320 ? 320 : 640;
    int h = mode_320 ? 240 : 480;

    FILE *f = fopen(path, "wb");
    if (!f) { perror(path); return; }
    fprintf(f, "P6\n%d %d\n255\n", w, h);

    uint32_t fb_base = 0x10000;            /* SDRAM byte 0x10000 = word 0x4000 */
    for (int y = 0; y < h; y++) {
        for (int x = 0; x < w; x++) {
            uint32_t xrgb;
            if (mode_8bpp) {
                /* Each fb byte indexes the LUT. Pixels pack 4 per word
                 * with `i mod 4` selecting the byte. */
                uint32_t idx = sdram[fb_base + y * w + x];
                xrgb = g_disp_lut[idx];
            } else {
                /* 32bpp XRGB packed in one pbus word */
                uint32_t off = fb_base + (uint32_t)(y * w + x) * 4u;
                xrgb = (uint32_t)sdram[off]
                     | ((uint32_t)sdram[off + 1] << 8)
                     | ((uint32_t)sdram[off + 2] << 16)
                     | ((uint32_t)sdram[off + 3] << 24);
            }
            uint8_t r = (uint8_t)(xrgb >> 16);
            uint8_t g = (uint8_t)(xrgb >> 8);
            uint8_t b = (uint8_t)(xrgb);
            fputc(r, f); fputc(g, f); fputc(b, f);
        }
    }
    fclose(f);
    fprintf(stderr, "sim_c: wrote %dx%d %s framebuffer to %s\n",
            w, h, mode_8bpp ? "8bpp" : "32bpp", path);
}

static const char *usage_text =
"usage: sim_c [options] file.s\n"
"\n"
"Assemble and run a program for one of the ISAs sim_c is built with\n"
"(every <arch>/isa.py in the toolchain; see isatool/arches.h).\n"
"\n"
"Options:\n"
"  -h, --help         Show this help and exit\n"
"  -trace FILE        Write a per-instruction execution trace to FILE\n"
"  -arch NAME         ISA to assemble and run (default cpu4; e.g. cpu5)\n"
"  -maxsteps N        Override the default instruction-step cap\n"
"                     (with -cores: N is ticks; each live core runs one\n"
"                     instruction per tick)\n"
"  -load ADDR FILE    Before running, copy FILE's bytes into SDRAM at ADDR\n"
"                     (0x10000 or above; may be repeated). For data too big\n"
"                     for the 64 KB image, e.g. a guest kernel\n"
"  -cores N           Simulate N CPU4 cores (default 1, max 1024). Every\n"
"                     core boots the same image at pc=0 with a private\n"
"                     64 KB BRAM; SDRAM and the display are shared.\n"
"                     Software reads CORE_ID at MMIO 0xFF24 (NCORES at\n"
"                     0xFF28) and branches. Deterministic round-robin.\n"
"  -soc               Model the KU5P cpu4_socN tile: each core is a barrel of 8\n"
"                     contexts sharing its BRAM (context launch via 0xFF24/0xFF28,\n"
"                     CORE_ID = {NCORES, id} at 0xFF2C) instead of the legacy\n"
"                     CORE_ID/NCORES words. Contexts 1..7 start parked.\n"
"  -dump FILE         Assemble and write a bytecode dump; do not execute\n"
"  -dumpfb            After running, dump the legacy 80x30 text framebuffer at 0xF000\n"
"  -fb FILE           After running, dump the bitmap framebuffer to FILE.ppm\n"
"                     (640x480 32bpp by default; honors DISP_MODE bits — 320x240 / 8bpp).\n"
"  -profile           Collect and print a per-source-line execution profile\n"
"  -pccount FILE      Write each executed pc with its execution count (tools/isaprof.py)\n"
"  -imap FILE         Write each assembled instruction's address, length and mnemonic\n"
"  -retire FILE       Write one line per retired instruction: pc, bytes, every\n"
"                     register and memory change, next pc\n"
"  -linemap FILE      Assemble and write a PC->source JSON map; do not execute\n"
"  -hex FILE          Assemble and write whitespace-delimited hex bytes; do not execute\n"
"\n"
"-dump, -linemap, and -hex stop after assembly and produce no runtime output.\n";

static void print_usage(FILE *f) { fputs(usage_text, f); }

int main(int argc, char **argv)
{
    int dumpfb = 0;
    const char *trace_path = NULL;
    const char *filename = NULL;
    const char *fb_out = NULL;
    long long maxsteps_override = 0;
    enum { MAX_LOADS = 16 };
    const char *load_path[MAX_LOADS]; uint32_t load_addr[MAX_LOADS]; int nloads = 0;

    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "-h") == 0 || strcmp(argv[i], "--help") == 0) {
            print_usage(stdout);
            return 0;
        }
        else if (strcmp(argv[i], "-trace") == 0 && i+1 < argc) trace_path = argv[++i];
        else if (strcmp(argv[i], "-profile") == 0) g_profile = 1;
        else if (strcmp(argv[i], "-pccount") == 0 && i+1 < argc) g_pccount_out = argv[++i];
        else if (strcmp(argv[i], "-imap") == 0 && i+1 < argc) {
            g_imap = fopen(argv[++i], "w");
            if (!g_imap) { perror(argv[i]); return 1; }
        }
        else if (strcmp(argv[i], "-retire") == 0 && i+1 < argc) {
            g_retire_out = fopen(argv[++i], "w");
            if (!g_retire_out) { perror(argv[i]); return 1; }
        }
        else if (strcmp(argv[i], "-dump") == 0 && i+1 < argc) g_dump_out = argv[++i];
        else if (strcmp(argv[i], "-dumpfb") == 0) dumpfb = 1;
        else if (strcmp(argv[i], "-fb") == 0 && i+1 < argc) fb_out = argv[++i];
        else if (strcmp(argv[i], "-arch") == 0 && i+1 < argc) {
            i++;
            const IsaArch *a = NULL;
            for (const IsaArch *c = isa_arches; c->name; c++) if (strcmp(c->name, argv[i]) == 0) a = c;
            if (!a) {
                fprintf(stderr, "sim_c: unknown arch '%s'; built with:", argv[i]);
                for (const IsaArch *c = isa_arches; c->name; c++) fprintf(stderr, " %s", c->name);
                fprintf(stderr, "\n");
                return 1;
            }
            g_arch = a; g_arch_name = a->name;
        }
        else if (strcmp(argv[i], "-maxsteps") == 0 && i+1 < argc) {
            maxsteps_override = atoll(argv[++i]);
        }
        else if (strcmp(argv[i], "-load") == 0 && i+2 < argc) {
            if (nloads == MAX_LOADS) { fprintf(stderr, "sim_c: at most %d -load files\n", MAX_LOADS); return 1; }
            load_addr[nloads] = (uint32_t)strtoul(argv[i+1], NULL, 0);
            load_path[nloads++] = argv[i+2];
            i += 2;
        }
        else if (strcmp(argv[i], "-soc") == 0) { g_soc = 1; }
        else if (strcmp(argv[i], "-cores") == 0 && i+1 < argc) {
            g_ncores = atoi(argv[++i]);
            if (g_ncores < 1 || g_ncores > SIM_MAX_CORES) {
                fprintf(stderr, "sim_c: -cores must be 1..%d\n", SIM_MAX_CORES);
                return 1;
            }
        }
        else if (strcmp(argv[i], "-linemap") == 0 && i+1 < argc) {
            g_linemap_out = argv[++i];
        }
        else if (strcmp(argv[i], "-hex") == 0 && i+1 < argc) {
            g_hex_out = argv[++i];
        }
        else filename = argv[i];
    }
    if (!filename) {
        print_usage(stderr);
        return 1;
    }

    if (maxsteps_override > 0) g_max_steps = maxsteps_override;
    if (g_profile) memset(prof_lineno, 0xff, sizeof(prof_lineno));  /* -1 = no mapping */
    char *src = read_file(filename);
    g_assembler_done = 0;
    if (g_profile) prof_split_lines(src);
    assemble_cpu4(src);
    free(src);
    for (int k = 0; k < nloads; k++) {
        /* SDRAM only: the BRAM image is the assembler's. The chip byte
         * range must not wrap, so an aliased address loads like its
         * un-aliased one. */
        uint32_t a = load_addr[k];
        if (!addr_is_sdram(a)) {
            fprintf(stderr, "sim_c: -load address 0x%x is not in SDRAM (0x10000 or above)\n", (unsigned)a);
            return 1;
        }
        FILE *lf = fopen(load_path[k], "rb");
        if (!lf) { perror(load_path[k]); return 1; }
        ensure_sdram();
        uint32_t chip = sdram_chip_byte(a);
        (void)fread(sdram + chip, 1, SDRAM_SIZE - chip, lf);
        int more = fgetc(lf) != EOF;
        fclose(lf);
        if (more) {
            fprintf(stderr, "sim_c: %s does not fit in SDRAM at 0x%x\n", load_path[k], (unsigned)a);
            return 1;
        }
    }
    if (g_linemap_out) dump_linemap(g_linemap_out);
    if (g_hex_out)     dump_hex(g_hex_out);
    { int i = find_sym("_globals_start"); if (i >= 0) g_write_threshold = syms[i].addr; }
    g_assembler_done = 1;
    if (g_dump_out) {
        uint16_t code_end = g_asm_end;
        { int i = find_sym("_globals_start"); if (i >= 0) code_end = syms[i].addr; }
        print_dump(code_end, g_asm_end, g_dump_out);
    }
    /* -dump / -linemap / -hex are assembly-only passes — do not execute. */
    if (g_dump_out || g_linemap_out || g_hex_out) return 0;
    if (trace_path) {
        g_trace_out = fopen(trace_path, "w");
        if (!g_trace_out) { perror(trace_path); return 1; }
    }
    g_nunits = g_soc ? g_ncores * SOC_NCTX : g_ncores;
    g_cores = calloc((size_t)g_nunits, sizeof(Core));
    g_tiles = calloc((size_t)g_ncores, sizeof(Tile));
    if (!g_cores || !g_tiles) { fprintf(stderr, "sim_c: out of memory for %d cores\n", g_ncores); return 1; }
    for (int i = 0; i < g_ncores; i++) {
        uint8_t *b = malloc(sizeof(mem));
        if (!b) { fprintf(stderr, "sim_c: out of memory for core %d BRAM\n", i); return 1; }
        memcpy(b, mem, sizeof(mem));
        if (g_soc) {
            for (int k = 0; k < SOC_NCTX; k++) { g_cores[i * SOC_NCTX + k].bram = b; g_cores[i * SOC_NCTX + k].H = (k != 0); }
        } else {
            g_cores[i].bram = b;
        }
    }
    g_bram = g_cores[0].bram;
    run_cpu4();
    if (g_trace_out) fclose(g_trace_out);
    if (g_retire_out) fclose(g_retire_out);
    if (dumpfb) dump_framebuffer();
    if (fb_out)  dump_bitmap_fb(fb_out);
    if (g_profile) print_profile();
    if (g_pccount_out) {
        FILE *pf = fopen(g_pccount_out, "w");
        if (pf) {
            for (int a = 0; a < 65536; a++)
                if (prof_count[a]) fprintf(pf, "%04x %u\n", a, prof_count[a]);
            fclose(pf);
        }
    }
    return 0;
}
